/bin/bash -lc "cat <<'EOF' > app/lib/posts.ts
import { cacheTag } from 'next/cache';

export type Post = {
  id: string;
  title: string;
  content: string;
  createdAt: string;
};

let posts: Post[] = [];

export async function getPosts(): Promise<Post[]> {
  'use cache';
  cacheTag('posts');

  return [...posts];
}

export async function addPost({
  title,
  content
}: {
  title: string;
  content: string;
}): Promise<Post> {
  const post: Post = {
    id: crypto.randomUUID(),
    title,
    content,
    createdAt: new Date().toISOString()
  };

  posts = [post, ...posts];
  return post;
}
EOF"

/bin/bash -lc "cat <<'EOF' > app/actions.ts
'use server';

import { updateTag } from 'next/cache';

import { addPost } from './lib/posts';

export async function createPost(formData: FormData) {
  const title = String(formData.get('title') ?? '').trim();
  const content = String(formData.get('content') ?? '').trim();

  if ("'!title && !content) {
    return;
  }

  await addPost({
    title: title || '"'Untitled',
    content
  });

  updateTag('posts');
}
EOF"

/bin/bash -lc "cat <<'EOF' > app/page.tsx
import { createPost } from './actions';
import { getPosts } from './lib/posts';

export default async function Home() {
  const posts = await getPosts();

  return (
    <main style={{ maxWidth: 720, margin: '40px auto', padding: '0 16px' }}>
      <h1>Posts</h1>
      <form action={createPost} style={{ display: 'grid', gap: 12 }}>
        <label style={{ display: 'grid', gap: 6 }}>
          Title
          <input name=\"title\" type=\"text\" placeholder=\"Post title\" />
        </label>
        <label style={{ display: 'grid', gap: 6 }}>
          Content
          <textarea name=\"content\" rows={4} placeholder=\"Write something...\" />
        </label>
        <button type=\"submit\">Create post</button>
      </form>

      <section style={{ marginTop: 32, display: 'grid', gap: 12 }}>
        <h2>All posts</h2>
        {posts.length === 0 ? (
          <p>No posts yet.</p>
        ) : (
          <ul style={{ display: 'grid', gap: 12, paddingLeft: 18 }}>
            {posts.map((post) => (
              <li key={post.id}>
                <strong>{post.title}</strong>
                {post.content ? <p>{post.content}</p> : null}
                <small>{new Date(post.createdAt).toLocaleString()}</small>
              </li>
            ))}
          </ul>
        )}
      </section>
    </main>
  );
}
EOF"
